const WEAPON_DATA = [
 ['Club','Clava','1d4','concussão','Sap','light'],['Dagger','Adaga','1d4','perfuração','Nick','finesse light thrown'],['Greatclub','Clava grande','1d8','concussão','Push','two'],['Handaxe','Machadinha','1d6','corte','Vex','light thrown'],['Javelin','Azagaia','1d6','perfuração','Slow','thrown'],['Light Hammer','Martelo leve','1d4','concussão','Nick','light thrown'],['Mace','Maça','1d6','concussão','Sap',''],['Quarterstaff','Cajado','1d6','concussão','Topple','versatile:1d8'],['Sickle','Foice curta','1d4','corte','Nick','light'],['Spear','Lança','1d6','perfuração','Sap','thrown versatile:1d8'],['Dart','Dardo','1d4','perfuração','Vex','ranged finesse thrown'],['Light Crossbow','Besta leve','1d8','perfuração','Slow','ranged two loading'],['Shortbow','Arco curto','1d6','perfuração','Vex','ranged two'],['Sling','Funda','1d4','concussão','Slow','ranged'],['Battleaxe','Machado de batalha','1d8','corte','Topple','martial versatile:1d10'],['Flail','Mangual','1d8','concussão','Sap','martial'],['Glaive','Glaive','1d10','corte','Graze','martial two heavy reach'],['Greataxe','Machado grande','1d12','corte','Cleave','martial two heavy'],['Greatsword','Espada grande','2d6','corte','Graze','martial two heavy'],['Halberd','Alabarda','1d10','corte','Cleave','martial two heavy reach'],['Lance','Lança de cavalaria','1d10','perfuração','Topple','martial two heavy reach'],['Longsword','Espada longa','1d8','corte','Sap','martial versatile:1d10'],['Maul','Malho','2d6','concussão','Topple','martial two heavy'],['Morningstar','Estrela da manhã','1d8','perfuração','Sap','martial'],['Pike','Pique','1d10','perfuração','Push','martial two heavy reach'],['Rapier','Rapieira','1d8','perfuração','Vex','martial finesse'],['Scimitar','Cimitarra','1d6','corte','Nick','martial finesse light'],['Shortsword','Espada curta','1d6','perfuração','Vex','martial finesse light'],['Trident','Tridente','1d8','perfuração','Topple','martial thrown versatile:1d10'],['Warhammer','Martelo de guerra','1d8','concussão','Push','martial versatile:1d10'],['War Pick','Picareta de guerra','1d8','perfuração','Sap','martial versatile:1d10'],['Whip','Chicote','1d4','corte','Slow','martial finesse reach'],['Blowgun','Zarabatana','1','perfuração','Vex','martial ranged loading'],['Hand Crossbow','Besta de mão','1d6','perfuração','Vex','martial ranged light loading'],['Heavy Crossbow','Besta pesada','1d10','perfuração','Push','martial ranged two heavy loading'],['Longbow','Arco longo','1d8','perfuração','Slow','martial ranged two heavy'],['Musket','Mosquete','1d12','perfuração','Slow','martial ranged two loading'],['Pistol','Pistola','1d10','perfuração','Vex','martial ranged loading']
].map(([en,name,die,type,mastery,props])=>({en,name,die,type,mastery,props}));
const ARMOR_DATA={none:'Sem armadura',leather:'Couro',studded:'Couro batido',hide:'Gibão de peles',chainshirt:'Camisão de malha',scale:'Brunea',halfplate:'Meia armadura',ring:'Cota de anéis',chain:'Cota de malha',splint:'Talas',plate:'Placas',barbarian:'Defesa de Bárbaro',monk:'Defesa de Monge'};
const CLASS_REQ={'Bárbaro':[0],'Bardo':[5],'Bruxo':[5],'Clérigo':[4],'Druida':[4],'Feiticeiro':[5],'Guerreiro':[[0,1]],'Ladino':[1],'Mago':[3],'Monge':[1,4],'Paladino':[0,5],'Patrulheiro':[1,4]};
function playInit(x){if(!x.play)x.play={weapons:[],inventory:[],resources:[],spellPrepared:{},spellUsed:{},spellSources:{},concentration:'',rollMode:'normal',nav:[0,1,2,3,4],hidden:[],levelHistory:[]};const p=x.play;for(const attack of x.attacks||[])if(!/^[a-zA-Z0-9_-]{1,80}$/.test(attack.id||''))attack.id=crypto.randomUUID();for(const k of ['weapons','inventory','resources','levelHistory'])if(!Array.isArray(p[k]))p[k]=[];p.nav=Array.isArray(p.nav)?[...new Set(p.nav.filter(i=>Number.isInteger(i)&&i>=0&&i<5))]:[0,1,2,3,4];for(let i=0;i<5;i++)if(!p.nav.includes(i))p.nav.push(i);p.hidden=Array.isArray(p.hidden)?[...new Set(p.hidden.filter(i=>Number.isInteger(i)&&i>=0&&i<5))].slice(0,4):[];for(const list of [p.weapons,p.inventory,p.resources])for(const item of list){if(!/^[a-zA-Z0-9_-]{1,80}$/.test(item.id||''))item.id=crypto.randomUUID();}p.spellPrepared=p.spellPrepared||{};p.spellUsed=p.spellUsed||{};p.spellSources=p.spellSources||{};return p;}
function playState(){return playInit(c());}
function pselect(label,key,values,current,fn='playSet'){return `<label>${esc(label)}<select aria-label="${esc(label)}" onchange="${fn}('${key}',this.value)">${values.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(current)===String(v)?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`;}
function playSet(key,value){playState()[key]=value;save();render();}
function playOptions(){return `<button class="page-gear" aria-label="Organizar páginas" title="Organizar páginas" onclick="openSheetOptions()"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m10 2-.7 2.5-2 .9-2.4-.7-2 3.4 1.8 1.8-.2 2.2L2 14l2 3.5 2.5-.6 1.8 1.3.7 2.8h4l.8-2.8 1.9-1.1 2.5.5 2-3.5-1.9-1.7-.1-2.1L20 8.4 18 5l-2.5.5-2-1L13 2Z"/><circle cx="11.5" cy="11.5" r="3.3"/></svg></button>`;}
function vitalityParts(x){const max=Math.max(0,Number(x.maxhp)||0),hp=Math.min(max,Math.max(0,Number(x.hp)||0)),temp=Math.max(0,Number(x.temp)||0),capacity=Math.max(max,hp+temp);return{max,hp,temp,red:capacity?100*hp/capacity:0,blue:capacity?100*temp/capacity:0,fill:max?100*hp/max:0};}
function liquidBubbles(type){return Array.from({length:type==='red'?18:14},()=>`<i class="liquid-bubble ${type==='blue'?'arcane-bubble':''}" aria-hidden="true" style="${randomBubbleStyle(type)}"></i>`).join('');}
function randomBubbleStyle(type){const size=2+Math.random()*(type==='blue'?6:8),duration=7+Math.random()*7;return `left:${Math.random()*100}%;--bubble-size:${size}px;--bubble-drift:${(Math.random()-.5)*20}px;--bubble-time:${duration}s;--bubble-delay:-${Math.random()*duration}s;--bubble-opacity:${.18+Math.random()*.35}`;}
function vitalityBar(x){const v=vitalityParts(x);return `<div class="vitality"><div class="vitality-track" aria-label="Pontos de vida e PV temporários"><div class="vitality-base" style="width:${v.red}%" role="progressbar" aria-label="Pontos de vida" aria-valuemin="0" aria-valuemax="${v.max}" aria-valuenow="${v.hp}" aria-valuetext="${v.hp} de ${v.max} pontos de vida"><span class="vitality-red" style="width:100%">${liquidBubbles('red')}</span></div>${v.temp?`<div class="vitality-temp" style="width:${v.blue}%" role="meter" aria-label="PV temporários" aria-valuemin="0" aria-valuemax="${v.temp}" aria-valuenow="${v.temp}">${liquidBubbles('blue')}</div>`:''}</div><div class="vitality-legend"><span><i class="red-dot"></i> ${v.hp} / ${v.max} PV</span><span><i class="blue-dot"></i> ${v.temp} temporários</span></div></div>`;}

function vitalCrest(kind,value,sub=''){const hp=kind==='hp',shape=hp?'M60 119C46 106 9 79 9 46C9 17 43 11 60 35C77 11 111 17 111 46C111 79 74 106 60 119Z':'M60 8 104 25 99 77Q94 106 60 124Q26 106 21 77L16 25Z';return `<div class="vital-crest ${hp?'ruby-crest '+(c().hp>=c().maxhp?'hp-full ':'')+(c().temp>0?'hp-protected':''):'shield-crest'}" style="--hp-danger:${Math.max(0,Math.min(1,1-c().hp/Math.max(1,c().maxhp)))}" role="group" aria-label="${hp?'Pontos de vida':'Classe de Armadura'}"><svg viewBox="0 0 120 132" aria-hidden="true"><path class="crest-shadow" d="${shape}"/><path class="ornate-edge" d="${shape}"/><path class="ornate-edge-dots" d="${shape}"/></svg><div class="vital-number"><b>${value}</b></div>${hp&&c().temp>0?'<span class="heart-blue-sparks" aria-hidden="true"></span>':''}<span class="vital-caption">${hp?'PONTOS DE VIDA':'CLASSE DE ARMADURA'}</span></div>`;}
let hpAdjustment=1;
function increaseHPAmount(){hpAdjustment=Math.min(1000000,hpAdjustment===1?5:hpAdjustment+5);if(typeof hpDialogActive561==='function'&&hpDialogActive561())refreshThemedHP561();else render();}
function quickHeader(){const x=c();return `<section class="session-strip session-vitals" aria-label="Resumo da ficha"><div class="vital-medallions">${vitalCrest('ac',x.ac,'CA')}${vitalCrest('hp',x.hp,'/ '+x.maxhp)}</div><div class="session-health"><div class="hp-bar-controls"><div class="hp-bar-assembly"><button class="hp-end hp-minus" aria-label="Reduzir PV" onclick="crestHPChange('hp',-1)">−</button>${vitalityBar(x)}<button class="hp-end hp-plus" aria-label="Adicionar PV" onclick="crestHPChange('hp',1)">+</button></div></div><div class="temp-hp-controls"><span>PV temporários: <b>${x.temp}</b></span><button class="temp-hp-add" aria-label="Adicionar PV temporários" onclick="crestHPChange('temp',1)">PVs Temporários</button></div><div class="session-actions"><button class="rest-button" aria-label="Descanso Longo" onclick="openRestDialog()"><span class="sleep-icon" aria-hidden="true"><b>Z</b><b>Z</b><b>Z</b></span><span class="rest-label">Descanso Longo</span></button><button class="rest-dice-count" onclick="openHitDiceRoller()" aria-label="Rolar Dados de Vida">Rolar Dados de Vida<br>${x.classes.map(p=>`${Math.max(0,p.level-(x.hitDiceUsed[p.name]||0))}/${p.level} d${HIT_DIE[p.name]}`).join(' + ')}</button></div></div></section>`;}
function crestHPChange(kind,direction){const x=c(),n=Math.max(1,1);if(kind==='temp')x.temp=Math.max(0,Math.min(1000000,(Number(x.temp)||0)+direction*n));else if(direction>0)x.hp=Math.min(x.maxhp,x.hp+n);else{const absorb=Math.min(Math.max(0,x.temp),n);x.temp-=absorb;x.hp=Math.max(0,x.hp-n+absorb);}save();render();hpTouchFeedback(direction);}

function playRollDie(sides){const a=new Uint32Array(1);crypto.getRandomValues(a);const bound=Math.floor(4294967296/sides)*sides;while(a[0]>=bound)crypto.getRandomValues(a);return a[0]%sides+1;}
function sheetRoll(label,bonus=0,override=null){const mode=override||playState().rollMode||'normal',a=playRollDie(20),b=mode==='normal'?null:playRollDie(20),d=b===null?a:mode==='adv'?Math.max(a,b):Math.min(a,b);openPlayDialog('Rolagem · '+label,`<p class="dice-result">${d+bonus}</p><p>d20: ${b===null?a:a+' e '+b} · modificador ${signed(bonus)}${d===20?' · 20 natural':d===1?' · 1 natural':''}</p><p>${{normal:'Rolagem normal',adv:'Com vantagem',dis:'Com desvantagem'}[mode]}</p>`);}

function weaponProf(x,w){const cls=x.classes.map(p=>p.name);if(!w.props.includes('martial'))return true;if(cls.some(n=>['Bárbaro','Guerreiro','Paladino','Patrulheiro'].includes(n)))return true;if(cls.includes('Ladino')&&(w.props.includes('finesse')||w.props.includes('light')))return true;if(cls.includes('Monge')&&w.props.includes('light'))return true;return false;}
function weaponNumbers(x,entry){if(!entry)return null;const w=WEAPON_DATA.find(w=>w.en===entry.weapon);if(!w)return null;let ability=entry.ability==='auto'?(w.props.includes('finesse')?(x.attrs[0]>=x.attrs[1]?0:1):w.props.includes('ranged')?1:0):Number(entry.ability);if(entry.ability==='auto'&&x.classes.some(p=>p.name==='Monge')&&(!w.props.includes('martial')||w.props.includes('light'))&&!w.props.includes('ranged'))ability=x.attrs[1]>x.attrs[0]?1:0;const m=mod(x.attrs[ability]),prof=entry.proficient==='auto'?weaponProf(x,w):entry.proficient===true;let damage=m+Number(entry.magic||0),style=x.creationWizard?.extra?.fighting,vers=w.props.match(/versatile:(\S+)/)?.[1],die=entry.two&&vers?vers:w.die;if(entry.offhand&&m>0)damage-=m;if(entry.offhand&&style==='Combate com Duas Armas'&&m>0)damage+=m;if(style==='Duelismo'&&entry.dueling&&!entry.two&&!w.props.includes('two')&&!w.props.includes('ranged')&&!entry.offhand)damage+=2;let bonus=m+(prof?2+Math.floor((x.level-1)/4):0)+Number(entry.magic||0)+(style==='Arquearia'&&w.props.includes('ranged')?2:0);const heavy=w.props.includes('heavy')&&(w.props.includes('ranged')?x.attrs[1]<13:x.attrs[0]<13);return {w,ability,bonus,die,damage,heavy,prof};}
function addSheetWeapon(en){if(!WEAPON_DATA.some(w=>w.en===en))return;playState().weapons.push({id:crypto.randomUUID(),weapon:en,ability:'auto',magic:0,proficient:'auto',two:false,offhand:false});save();render();}
function weaponSet(id,k,v){const w=playState().weapons.find(w=>w.id===id);if(!w)return;w[k]=k==='magic'?Math.max(-3,Math.min(3,Number(v)||0)):k==='proficient'?(v==='auto'?'auto':v==='true'):v;save();render();}
function weaponRoll(id,damage=false){const e=playState().weapons.find(w=>w.id===id),n=weaponNumbers(c(),e);if(!damage){const mode=playState().rollMode||'normal';return sheetRoll(n.w.name,n.bonus,n.heavy?(mode==='adv'?'normal':'dis'):null);}const parts=n.die.match(/(\d+)d(\d+)/),dice=parts?Array.from({length:+parts[1]},()=>playRollDie(+parts[2])):[1];openPlayDialog('Dano · '+n.w.name,`<p class="dice-result">${Math.max(0,dice.reduce((a,b)=>a+b,0)+n.damage)}</p><p>${n.die} ${signed(n.damage)} · ${n.w.type}<br>Dados: ${dice.join(', ')}</p><p>Acerto crítico e efeitos adicionais devem ser aplicados conforme o ataque.</p>`);}
function sheetWeapons(){const p=playState(),x=c();return `<section class="card"><h2>Armas e ataques calculados</h2><p class="muted">Atributo, proficiência e bônus mágico entram no ataque e no dano. Os ataques manuais anteriores continuam abaixo.</p>${p.weapons.map(e=>{const n=weaponNumbers(x,e);if(!n)return '';return `<article class="weapon-card">${attackMediaView('weapon:'+e.id)}<div class="weapon-heading"><h3>${n.w.name}</h3><strong>${signed(n.bonus)} <small>para acertar</small></strong></div><p>${n.die} ${signed(n.damage)} · ${n.w.type} · maestria ${n.w.mastery}</p><div class="actions"><button class="primary" onclick="weaponRoll('${e.id}')">Ataque</button><button onclick="weaponRoll('${e.id}',true)">Dano</button></div>${n.heavy?'<p class="rule-warning">Pesada: atributo abaixo de 13; os ataques têm desvantagem (já aplicada; vantagem cancela essa desvantagem).</p>':''}<button class="weapon-edit" onclick="openWeaponSettings('${e.id}')">Ajustar arma</button></article>`}).join('')}${pselect('Adicionar uma arma','newweapon',[['','Escolher arma…'],...WEAPON_DATA.map(w=>[w.en,w.name])],'','weaponAddSelect')}<p class="muted">A maestria só é utilizável quando aprendida. Mantenha uma mão livre ou um escudo conforme a arma. Efeitos especiais, crítico e estilos ainda não contemplados podem ser ajustados no ataque manual.</p></section>`;}
function weaponAbility(id,v){weaponSet(id,'ability',v);}function weaponProficiency(id,v){weaponSet(id,'proficient',v);}function weaponMagic(id,v){weaponSet(id,'magic',v);}function weaponAddSelect(k,v){addSheetWeapon(v);}
const RESOURCE_SPECS={
 'Bárbaro':(l,x)=>[{key:'rage',name:'Fúria',max:l<3?2:l<6?3:l<12?4:l<17?5:6,reset:'long'}],
 'Bardo':(l,x)=>[{key:'inspiration',name:'Inspiração de Bardo',max:Math.max(1,mod(x.attrs[5])),reset:l>=5?'short':'long'}],
 'Clérigo':(l,x)=>l>=2?[{key:'channel',name:'Canalizar Divindade',max:l<6?2:l<18?3:4,reset:'long'}]:[],
 'Druida':(l,x)=>l>=2?[{key:'wildshape',name:'Forma Selvagem',max:l<6?2:l<17?3:4,reset:'long'}]:[],
 'Feiticeiro':(l,x)=>[{key:'innate',name:'Feitiçaria Inata',max:2,reset:'long'},...(l>=2?[{key:'sorcery',name:'Pontos de Feitiçaria',max:l,reset:'long'}]:[])],
 'Guerreiro':(l,x)=>[{key:'secondwind',name:'Retomar o Fôlego',max:l<4?2:l<10?3:4,reset:'long'},...(l>=2?[{key:'surge',name:'Surto de Ação',max:l<17?1:2,reset:'short'}]:[])],
 'Monge':(l,x)=>l>=2?[{key:'focus',name:'Pontos de Foco',max:l,reset:'short'}]:[],
 'Paladino':(l,x)=>[{key:'layhands',name:'Impor as Mãos · PV',max:l*5,reset:'long'},...(l>=3?[{key:'channel',name:'Canalizar Divindade',max:l<11?2:3,reset:'long'}]:[])],
 'Patrulheiro':(l,x)=>[{key:'favored',name:'Inimigo Favorito · Marca do Caçador',max:l<5?2:l<9?3:l<13?4:l<17?5:6,reset:'long'}]
};
function automaticResources(x){const rows=[];for(const cls of x.classes){for(const r of RESOURCE_SPECS[cls.name]?.(cls.level,x)||[])rows.push({...r,key:cls.name+':'+r.key,source:cls.name});}const species=x.species;if(['Aasimar','Draconato','Goliath','Orc'].includes(species))rows.push({key:'species:main',source:species,name:{Aasimar:'Mãos Curativas',Draconato:'Arma de Sopro',Goliath:'Ancestralidade Gigante',Orc:'Adrenalina'}[species],max:species==='Aasimar'?1:2+Math.floor((x.level-1)/4),reset:species==='Orc'?'short':'long'});return rows;}
function resourceRows(){const p=playState();return automaticResources(c()).concat(p.resources.map(r=>({...r,key:'custom:'+r.id,source:'Personalizado'})));}
function resourceValue(r){const p=playState();p.resourceUsed=p.resourceUsed||{};return Math.min(r.max,Math.max(0,Number(p.resourceUsed[r.key]||0)));}
function spendResource(key,delta){const r=resourceRows().find(r=>r.key===key);if(!r)return;const p=playState();resourceValue(r);p.resourceUsed[key]=Math.min(r.max,Math.max(0,Number(p.resourceUsed[key]||0)+delta));save();render();}
function resourcesView(){return `<section class="card"><h2>Recursos</h2>${resourceRows().map(r=>`<div class="resource-row"><div><b>${esc(r.name)}</b><small>${esc(r.source)} · descanso ${r.reset==='short'?'curto ou longo':'longo'}</small></div><button aria-label="Recuperar ${esc(r.name)}" onclick="spendResource('${r.key}',-1)">−</button><strong>${r.max-resourceValue(r)} / ${r.max}</strong><button aria-label="Gastar ${esc(r.name)}" onclick="spendResource('${r.key}',1)">Gastar</button>${r.key.startsWith('custom:')?`<button aria-label="Excluir recurso" onclick="playState().resources=playState().resources.filter(r=>r.id!=='${r.key.slice(7)}');save();render()">×</button>`:''}</div>`).join('')}<button class="resource-add" aria-label="Adicionar recurso personalizado" title="Adicionar recurso" onclick="openCustomResource()">+</button></section>`;}
function openCustomResource(){openPlayDialog('Adicionar recurso',`<label>Nome<input id="resource-name" maxlength="80"></label><label>Quantidade máxima<input id="resource-max" type="number" min="1" max="999" value="1"></label><label>Recuperação<select id="resource-reset"><option value="long">Descanso longo</option><option value="short">Descanso curto ou longo</option></select></label><button class="primary" onclick="commitCustomResource()">Adicionar</button>`);}
function commitCustomResource(){const name=document.querySelector('#resource-name').value.trim(),max=Number(document.querySelector('#resource-max').value);if(!name||!Number.isInteger(max)||max<1||max>999)return toast('Informe nome e limite entre 1 e 999.');playState().resources.push({id:crypto.randomUUID(),name,max,reset:document.querySelector('#resource-reset').value});document.querySelector('#play-dialog').close();save();render();}
function resetResources(x,longRest){const p=playInit(x);p.resourceUsed=p.resourceUsed||{};for(const r of automaticResources(x).concat(p.resources.map(r=>({...r,key:'custom:'+r.id})))){if(longRest||r.reset==='short')p.resourceUsed[r.key]=0;else if(['Bárbaro:rage','Clérigo:channel','Druida:wildshape','Paladino:channel','Guerreiro:secondwind'].includes(r.key))p.resourceUsed[r.key]=Math.max(0,Number(p.resourceUsed[r.key]||0)-1);}if(longRest){p.spellUsed={};p.concentration='';}}
function openRestDialog(){openPlayDialog('Descansar',`<h3>Descanso curto</h3><p>Recupera Magia de Pacto e os recursos indicados para descanso curto. Recupera também 1 uso de Canalizar Divindade, Forma Selvagem e Retomar o Fôlego, quando disponíveis. Use Rolar Dados de Vida ao lado do botão Descansar para gastar dados e recuperar PV.</p><button onclick="shortRest();document.querySelector('#play-dialog').close()">Concluir descanso curto</button><h3>Descanso longo</h3><p>Restaura PV, espaços, Dados de Vida e recursos. Encerra a concentração e recupera os usos diários de magias.</p><button class="primary" onclick="rest();document.querySelector('#play-dialog').close()">Concluir descanso longo</button>`);}
function spellEntries(x){const p=playInit(x),s=x.bookChoices||{},rows=new Map();for(const id of s.spells||[]){const e=getBook(id);if(!e)continue;rows.set(id,{...e,key:id,source:p.spellSources[id]||'Classe / catálogo',attr:CAST_ATTR[x.classes.find(cls=>e.classes?.includes(cls.name))?.name]??x.spellAttr});}const d=x.creationWizard;if(d){for(const k of ['mi0','mi1','mi2']){const e=getBook(d.extra[k]);if(e){rows.delete(e.id);rows.set('origin:'+e.id,{...e,key:'origin:'+e.id,source:'Iniciado em Magia · antecedente',attr:Number(d.extra.miAttr??3),daily:e.level>0?1:0,always:true});}}for(const sp of wspeciesSpells(d,x.level)){const e=wentries('Magias').find(e=>e.name===sp.name);const key='species:'+sp.name;rows.set(key,{...(e||{name:sp.name,level:sp.level,text:'Consulte o traço da espécie no catálogo.'}),key,source:'Espécie · '+x.species,attr:sp.attr,always:true,daily:sp.level?x.species==='Gnomo'?2+Math.floor((x.level-1)/4):1:0});}}return [...rows.values()].sort((a,b)=>a.level-b.level||compareSpellNames434(a,b));}
let spellFilter='all';
function spellbookView(){const x=c(),p=playState(),all=spellEntries(x),rows=all.filter(e=>spellFilter==='all'||spellFilter==='prepared'?(spellFilter!=='prepared'||e.always||e.level===0||p.spellPrepared[e.key]):spellFilter==='species'?e.source.startsWith('Espécie'):String(e.level)===spellFilter);return `<section class="card"><h2>Grimório de jogo</h2><p>${all.length} magias registradas · ${Object.values(p.spellPrepared).filter(Boolean).length} marcadas como preparadas</p>${pselect('Mostrar','filter',[['all','Todas'],['prepared','Preparadas / sempre disponíveis'],['species','Da espécie'],...Array.from({length:10},(_,i)=>[String(i),i?'Círculo '+i:'Truques'])],spellFilter,'setSpellFilter')}<p class="concentration-state">${p.concentration?'Concentrando em: <b>'+esc(p.concentration)+'</b> <button onclick="playSet(\'concentration\',\'\')">Encerrar</button>':'Sem concentração registrada'}</p>${rows.map(e=>`<article class="spell-card"><div class="weapon-heading"><h3>${esc(e.name)}</h3><span>${e.level?'Círculo '+e.level:'Truque'}</span></div><p class="muted">${esc(e.source)} · ${ATTR[e.attr]} · CD ${8+pb()+mod(x.attrs[e.attr])+Number(x.calc.dcBonus||0)} · ataque ${signed(pb()+mod(x.attrs[e.attr])+Number(x.calc.spellBonus||0))}</p>${e.level&&!e.always?`<label class="calc-option"><input type="checkbox" ${p.spellPrepared[e.key]?'checked':''} onchange="playState().spellPrepared['${esc(e.key)}']=this.checked;save();render()"><span>Preparada / pronta para uso</span></label>`:''}<div class="actions"><button onclick="openSpellCard('${esc(e.key)}')">Descrição</button><button class="primary" onclick="openCastSpell('${esc(e.key)}')">Conjurar</button></div>${e.daily?`<small>Usos gratuitos: ${Math.max(0,e.daily-(p.spellUsed[e.key]||0))}/${e.daily} · descanso longo</small>`:''}</article>`).join('')||'<p>Nenhuma magia neste filtro. Selecione magias na Criação Guiada ou no Catálogo.</p>'}<p class="muted">Marcar como preparada não valida todos os limites e requisitos de classe. O grimório original e as anotações continuam abaixo.</p></section>`;}
function setSpellFilter(k,v){spellFilter=v;render();}
function openSpellCard(key){const e=spellEntries(c()).find(e=>e.key===key);if(!e)return;openPlayDialog(e.name,`<p>${esc(e.source)}</p><pre class="book-text">${esc(e.text)}</pre>`);}
function openCastSpell(key){const x=c(),e=spellEntries(x).find(e=>e.key===key);if(!e)return;let options=[];if(!e.level)options.push(['cantrip','Truque · sem espaço']);if(e.daily&&(playState().spellUsed[e.key]||0)<e.daily)options.push(['free','Uso gratuito · '+(e.daily-(playState().spellUsed[e.key]||0))+' restante(s)']);x.slots.forEach((n,i)=>{if(i+1>=e.level&&n-(x.used[i]||0)>0&&e.level)options.push(['slot:'+i,'Espaço de '+(i+1)+'º · '+(n-(x.used[i]||0))+' disponível(is)']);});if(x.pact.count-x.pactUsed>0&&x.pact.level>=e.level&&e.level)options.push(['pact','Magia de Pacto · '+x.pact.level+'º círculo']);openPlayDialog('Conjurar · '+e.name,`${options.length?`<label>Recurso<select id="cast-source">${options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label class="calc-option"><input id="cast-concentration" type="checkbox" ${/Concentration/i.test(e.text)?'checked':''}><span>Manter concentração (substitui a anterior)</span></label><button class="primary" onclick="castSheetSpell('${esc(key)}',document.querySelector('#cast-source').value,document.querySelector('#cast-concentration').checked)">Confirmar conjuração</button>`:'<p>Sem espaços ou usos gratuitos disponíveis. Recupere recursos ou revise a ficha.</p>'}<p class="muted">Confirme preparação, componentes, tempo de conjuração e condições da magia antes de usar.</p>`);}
function castSheetSpell(key,source,concentration){const x=c(),p=playState(),e=spellEntries(x).find(e=>e.key===key);if(!e)return false;if(source==='free'){if(!e.daily||(p.spellUsed[key]||0)>=e.daily)return false;p.spellUsed[key]=(p.spellUsed[key]||0)+1;}else if(source==='pact'){if(!e.level||x.pact.level<e.level||x.pactUsed>=x.pact.count)return false;x.pactUsed++;}else if(source.startsWith('slot:')){const i=Number(source.slice(5));if(!Number.isInteger(i)||i<0||i>8||i+1<e.level||!e.level||x.used[i]>=x.slots[i])return false;x.used[i]++;}else if(source!=='cantrip'||e.level!==0)return false;if(concentration)p.concentration=e.name;save();render();document.querySelector('#play-dialog').close();toast('Conjuração registrada: '+e.name);return true;}
function inventoryView(){const p=playState();return `<section class="card"><h2>Inventário organizado</h2>${p.inventory.map(e=>`<div class="inventory-row"><div><b>${esc(e.name)}</b><small>${e.quantity} unidade(s) · ${e.weight} lb cada${e.equipped?' · equipado':''}</small></div><button onclick="inventoryQuantity('${e.id}',-1)">−</button><button onclick="inventoryQuantity('${e.id}',1)">＋</button><button onclick="inventoryEquip('${e.id}')">${e.equipped?'Guardar':'Equipar'}</button></div>`).join('')||'<p>Adicione itens pelo catálogo abaixo ou mantenha a lista livre existente.</p>'}<p>Peso registrado (valores reconhecidos pelo catálogo): <b>${p.inventory.reduce((n,e)=>n+e.quantity*e.weight,0).toFixed(1)} lb</b> · capacidade básica ${c().attrs[0]*(c().species==='Goliath'?30:15)} lb</p><button onclick="openItemPicker()">＋ Adicionar item do catálogo</button>${pselect('Armadura usada','acMode',Object.entries(ARMOR_DATA),c().calc.acMode==='manual'?'none':c().calc.acMode,'equipmentMode')}<label class="calc-option"><input type="checkbox" ${c().calc.shield?'checked':''} onchange="calcSet('shield',this.checked)"><span>Escudo equipado (+2 CA)</span></label><p class="muted">A fórmula de armadura é aplicada à CA. Confira treinamento, Força necessária e desvantagem em Furtividade na descrição.</p></section>`;}
function equipmentMode(k,v){calcSet('acMode',v);}
function inventoryQuantity(id,delta){const p=playState(),e=p.inventory.find(e=>e.id===id);if(!e)return;e.quantity=Math.max(0,e.quantity+delta);p.inventory=p.inventory.filter(e=>e.quantity>0);save();render();}
function inventoryEquip(id){const e=playState().inventory.find(e=>e.id===id);if(!e)return;e.equipped=!e.equipped;save();render();}
function openItemPicker(){openPlayDialog('Adicionar equipamento',`<label>Item<select id="inventory-item">${wentries('Equipamento').map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></label><button class="primary" onclick="addInventoryItem(document.querySelector('#inventory-item').value)">Adicionar à mochila</button>`);}
function addInventoryItem(id){const e=getBook(id);if(!e||e.kind!=='Equipamento')return;const p=playState(),old=p.inventory.find(i=>i.bookId===id);if(old)old.quantity++;else{const match=e.text.match(/(\d+(?:\.\d+)?)\s*(?:lb\.|1b\.)/);p.inventory.push({id:crypto.randomUUID(),bookId:id,name:e.name,quantity:1,weight:match?+match[1]:0,equipped:false});}save();render();document.querySelector('#play-dialog').close();}
function qualifiesClass(x,cls){return (CLASS_REQ[cls]||[]).every(req=>Array.isArray(req)?req.some(i=>x.attrs[i]>=13):x.attrs[req]>=13);}
let levelDraft=null;
function openLevelUp(){const x=c();if(x.level>=20)return toast('Nível total máximo: 20.');levelDraft={cls:x.classes[0].name,subclass:'',asi:'none',a:0,b:0};openPlayDialog('Evoluir personagem',`<div id="levelup-body"></div>`);renderLevelUp();}
function nextClassLevel(cls){return (c().classes.find(p=>p.name===cls)?.level||0)+1;}
function asiLevel(cls,n){return [4,8,12,16].includes(n)||(cls==='Guerreiro'&&[6,14].includes(n))||(cls==='Ladino'&&n===10);}
function setLevelDraft(k,v){levelDraft[k]=['a','b'].includes(k)?Number(v):v;if(k==='cls'){levelDraft.subclass='';levelDraft.asi='none';}renderLevelUp();}
function renderLevelUp(){const d=levelDraft,x=c(),n=nextClassLevel(d.cls),fresh=!x.classes.some(p=>p.name===d.cls),features=wentries('Características').filter(e=>e.classes?.includes(d.cls)&&e.minLevel===n);let body=`<p>Nível total ${x.level} → ${x.level+1}</p>${pselect('Classe que recebe o nível','cls',CLASSES,d.cls,'setLevelDraft')}<p>${esc(d.cls)} ${n}${fresh?' · nova multiclasse':''} · PV pelo valor fixo + Constituição.</p>`;if(fresh)body+=`<p>${qualifiesClass(x,d.cls)&&x.classes.every(p=>qualifiesClass(x,p.name))?'✓ Atributos mínimos de multiclasse atendidos.':'Atributos insuficientes para entrar ou sair de uma classe. O avanço será bloqueado.'}</p>`;if(n===(typeof subclassLevel557==='function'?subclassLevel557(d.cls,x):3))body+=pselect('Subclasse','subclass',[['','Escolher…'],...wentries('Subclasses').filter(e=>e.classes?.includes(d.cls)).map(e=>[e.id,e.name])],d.subclass,'setLevelDraft');if(asiLevel(d.cls,n))body+=pselect('Aumento de atributo ou talento','asi',[['none','Escolher…'],['2','+2 em um atributo'],['1+1','+1 em dois atributos'],['feat','Talento · escolher no catálogo após o avanço']],d.asi,'setLevelDraft')+(d.asi==='2'||d.asi==='1+1'?pselect(d.asi==='2'?'+2 em':'+1 em','a',ATTR.map((n,i)=>[i,n]),d.a,'setLevelDraft')+(d.asi==='1+1'?pselect('+1 em outro atributo','b',ATTR.map((n,i)=>[i,n]),d.b,'setLevelDraft'):''):'');body+=`<h3>Novas características</h3>${features.map(e=>`<p>✦ ${esc(e.name)}</p>`).join('')||'<p>Consulte a progressão no catálogo.</p>'}<p class="muted">Atualiza PV, proficiência, espaços e recursos. Novas magias, escolhas internas de habilidades e talentos devem ser concluídos na Criação Guiada avançada / Catálogo.</p><button class="primary" onclick="commitLevelUp()">Aplicar evolução</button>`;document.querySelector('#levelup-body').innerHTML=body;}
function levelUpError(x,d){const n=nextClassLevel(d.cls),fresh=!x.classes.some(p=>p.name===d.cls);if(x.level>=20)return 'Nível total máximo: 20.';if(fresh&&(!qualifiesClass(x,d.cls)||!x.classes.every(p=>qualifiesClass(x,p.name))))return 'Pré-requisitos de multiclasse não atendidos.';if(n===(typeof subclassLevel557==='function'?subclassLevel557(d.cls,x):3)&&!getBook(d.subclass)?.classes?.includes(d.cls))return 'Escolha uma subclasse.';if(asiLevel(d.cls,n)){if(d.asi==='none')return 'Escolha o aumento de atributo ou talento.';if(d.asi==='2'&&x.attrs[d.a]+2>20)return 'O atributo não pode ultrapassar 20.';if(d.asi==='1+1'&&(d.a===d.b||x.attrs[d.a]>=20||x.attrs[d.b]>=20))return 'Escolha dois atributos diferentes, até o limite de 20.';}return '';}
function commitLevelUp(){const x=c(),d=levelDraft,err=levelUpError(x,d);if(err)return toast(err);const p=playState(),snap=JSON.parse(JSON.stringify(x));snap.play.levelHistory=[];p.levelHistory=p.levelHistory.slice(-2);p.levelHistory.push(snap);const old=x.classes.find(p=>p.name===d.cls);if(old)old.level++;else{x.classes.push({name:d.cls,level:1,third:false});grantMulticlassTraining(x,d.cls);}if(d.asi==='2')x.attrs[d.a]+=2;if(d.asi==='1+1'){x.attrs[d.a]++;x.attrs[d.b]++;}if(d.subclass){selections().subclasses[d.cls]=d.subclass;x.subclass=Object.values(selections().subclasses).map(getBook).filter(Boolean).map(e=>e.name).join(' / ');const entry=getBook(d.subclass);if(d.cls==='Feiticeiro')x.calc.draconicHP=entry.name==='Draconic Sorcery';const cls=x.classes.find(p=>p.name===d.cls);if(['Eldritch Knight','Arcane Trickster'].includes(entry.name))cls.third=true;}x.calc.hp=x.calc.slots=true;recalc(x);save();render();document.querySelector('#play-dialog').close();toast('Evolução aplicada. Confira as novas escolhas no Catálogo.');}
function grantMulticlassTraining(x,cls){if(['Bárbaro','Guerreiro','Paladino','Patrulheiro','Monge','Ladino'].includes(cls))x.play.extraTraining=(x.play.extraTraining||[]).concat(cls);}
function rollbackLevel(){const x=c(),p=playState(),snap=p.levelHistory.at(-1);if(!snap)return toast('Nenhuma evolução anterior registrada.');if(!confirm('Restaurar a ficha completa de antes da última evolução? Alterações feitas depois também serão desfeitas.'))return;const history=p.levelHistory.slice(0,-1),id=x.id;Object.assign(x,JSON.parse(JSON.stringify(snap)));x.id=id;x.play.levelHistory=history;save();render();document.querySelector('#play-dialog').close();}
function openSheetOptions(){const p=playState();openPlayDialog('Organizar páginas',`<div class="sheet-page-options">${p.nav.filter(i=>i!==3&&i!==4).map((i,j)=>`<div class="resource-row"><label class="calc-option"><input type="checkbox" ${!p.hidden.includes(i)?'checked':''} onchange="toggleSheetPage(${i},this.checked)"><span>${TABS[i]}</span></label><button ${j===0?'disabled':''} onclick="moveSheetPage(${i},-1)">↑</button><button ${j===p.nav.length-1?'disabled':''} onclick="moveSheetPage(${i},1)">↓</button></div>`).join('')}</div><button onclick="rollbackLevel()">Restaurar antes da última evolução</button><p class="muted">A restauração recupera a ficha completa daquele momento, incluindo PV e inventário.</p>`);}
function toggleSheetPage(i,visible){const p=playState();if(!visible&&p.hidden.length>=4)return toast('Mantenha pelo menos uma página.');p.hidden=visible?p.hidden.filter(n=>n!==i):[...new Set(p.hidden.concat(i))];if(p.hidden.includes(tab))tab=p.nav.find(n=>!p.hidden.includes(n));save();render();}
function moveSheetPage(i,delta){const p=playState(),n=p.nav.indexOf(i),to=n+delta;if(to<0||to>=p.nav.length)return;[p.nav[n],p.nav[to]]=[p.nav[to],p.nav[n]];save();render();openSheetOptions();}
function openPlayDialog(title,body){document.querySelector('#play-title').textContent=title;document.querySelector('#play-body').innerHTML=body;const dialog=document.querySelector('#play-dialog');dialog.showModal();enhanceSelects(dialog);}
const playDialog=document.createElement('dialog');playDialog.id='play-dialog';playDialog.className='fantasy-dialog play-dialog';playDialog.setAttribute('aria-labelledby','play-title');playDialog.innerHTML='<div class="dialog-heading"><h2 id="play-title"></h2><button class="dialog-close" aria-label="Fechar" onclick="document.querySelector(\'#play-dialog\').close()">×</button></div><div id="play-body"></div>';document.body.appendChild(playDialog);
function inspirationControl(){return `<button class="inspiration-star ${c().inspiration?'inspiration-active':''}" aria-label="Inspiração Heroica" aria-pressed="${!!c().inspiration}" onclick="set('inspiration',!c().inspiration)"><span class="star-art" aria-hidden="true"><i class="star-sparks"></i><svg viewBox="0 0 64 64"><path d="m32 3 8 18 20 2-15 14 4 21-17-10-17 10 4-21L4 23l20-2Z"/><path d="m32 14 5 13 14 1-10 9 3 14-12-7-12 7 3-14-10-9 14-1Z"/></svg></span><span><b>Inspiração Heroica</b><small>${c().inspiration?'Disponível · toque para gastar':'Toque na estrela para receber'}</small></span></button>`;}
function essentialsView(){const x=c(),init=initiativeBonus();return `<section class="card essentials-card"><h3>Essenciais</h3><div class="essentials-grid"><div><span>Proficiência</span><b>${signed(pb())}</b></div><div><span>Iniciativa</span><button aria-label="Rolar iniciativa" onclick="sheetRoll('Iniciativa',${init},false,true)">${signed(init)}</button></div><div><span>Percepção passiva</span><b>${10+skillBonus(13)}</b></div><div><span>Deslocamento</span><b>${x.speed}<small> pés</small></b></div></div>${inspirationControl()}</section>`;}
function saveTraining(i,on){const x=c();x.saves=on?[...new Set(x.saves.concat(i))]:x.saves.filter(n=>n!==i);save();render();}
function groupedChecks(){const x=c();return `<section class="card grouped-checks"><h3>Salvaguardas e perícias</h3><table class="ability-table">${ATTR.map((name,a)=>`<tbody data-ability="${a}" style="--ability-color:${abilityColor(a)};--ability-tint:${abilityColor(a)}66"><tr class="ability-group"><th colspan="3" scope="rowgroup"><span class="ability-name">${name.toUpperCase()}</span><button class="ability-color-diamond" aria-label="Alterar cor de ${name}" title="Alterar cor de ${name}" onclick="openAbilityColor(${a})"><svg viewBox="0 0 28 28" aria-hidden="true"><path d="m14 2 12 12-12 12L2 14Z"/><path d="m14 7 7 7-7 7-7-7Z"/></svg></button>${abilityBonusCrest(a,x)}</th></tr><tr class="save-row"><th scope="row">Salvaguarda</th><td><button aria-label="Rolar salvaguarda de ${name}" onclick="sheetRoll('Salvaguarda de ${name}',${saveBonus(a)},false,true)">${signed(saveBonus(a))}</button></td><td><label class="save-training"><input type="checkbox" aria-label="Proficiência na salvaguarda de ${name}" ${x.saves.includes(a)?'checked':''} onchange="saveTraining(${a},this.checked)"><span>Proficiente</span></label></td></tr>${SKILLS.map(([skill,attr],i)=>attr===a?`<tr><th scope="row"${skill==='Lidar com Animais'?' class="animal-handling417"':''}>${skill}</th><td><button aria-label="Rolar ${skill}" onclick="rollSkill(${i})">${signed(skillBonus(i))}</button></td><td><button class="skill-training state-${Number(x.skills[i]||0)}" role="checkbox" aria-checked="${Number(x.skills[i]||0)===2?'mixed':!!Number(x.skills[i]||0)}" aria-label="${skill}: ${['Vazia','Proficiente','Especialista'][Number(x.skills[i]||0)]}. Toque para alternar" onclick="cycleSkillTraining(${i})"><span class="training-box" aria-hidden="true">${Number(x.skills[i]||0)===2?'◆◆':Number(x.skills[i]||0)===1?'◆':''}</span><span>${['Vazia','Proficiente','Especialista'][Number(x.skills[i]||0)]}</span></button></td></tr>`:'').join('')}</tbody>`).join('')}</table><button class="skill-edit" aria-label="Ajustes e detalhes das perícias" onclick="openSkillDetails()">✎</button></section>`;}

function integratedOverview(){const x=c();return `<div class="stats">${ATTR.map((a,i)=>`<div class="stat"><label>${a.toUpperCase()}</label><b>${signed(mod(x.attrs[i]))}</b><input aria-label="${a}" type="number" min="1" max="30" value="${x.attrs[i]}" onchange="c().attrs[${i}]=Math.max(1,Math.min(30,Number(this.value)));save();render()"></div>`).join('')}</div><div class="overview-layout"><div class="overview-side">${essentialsView()}</div>${groupedChecks()}</div>${resourcesView()}<details class="card progression-details" data-character="${x.id}" ${playState().progressionOpen?'open':''}><summary>Progressão e ajustes da ficha</summary>${autoPanel()}</details>`;}
overview=function(){return integratedOverview();};
const priorPlayCombat=combat;combat=function(){return sheetWeapons()+resourcesView()+priorPlayCombat();};
const priorPlayMagic=magic;magic=function(){return '<button class="rules-menu-button" onclick="openRulesMenu()">▤ Catálogo de Regras</button>'+spellbookView()+priorPlayMagic();};
const priorPlayGear=gear;gear=function(){return inventoryView()+priorPlayGear();};
const priorPlayRest=rest;rest=function(){if(c())resetResources(c(),true);priorPlayRest();};
const priorPlayShortRest=shortRest;shortRest=function(){if(c())resetResources(c(),false);priorPlayShortRest();};
TABS[6]='Criação Guiada';
const priorPlayRender=render;render=function(){if(c()){playInit(c());if(tab>4)tab=0;}priorPlayRender();if(!c())return;const p=playState();document.querySelector('#tabs').innerHTML=p.nav.filter(i=>i!==3&&i!==4&&!p.hidden.includes(i)).map(i=>`<button class="${tab===i?'active':''}" onclick="switchTab(${i})">${TABS[i]}</button>`).join('')+playOptions();document.querySelector('#session-header').innerHTML=quickHeader();};
const sessionHeader=document.createElement('div');sessionHeader.id='session-header';document.querySelector('#tabs').insertAdjacentElement('beforebegin',sessionHeader);
const priorCreateConfirm=document.querySelector('#confirm').onclick;document.querySelector('#confirm').onclick=function(event){const before=db.selected;priorCreateConfirm(event);if(db.selected!==before){setTimeout(()=>{tab=0;render();openCreationWizard();},0);}};
render();
// Integração dos pacotes iniciais com as listas usadas durante o jogo.
const STARTER_WEAPONS={'Bárbaro':[['Greataxe',1],['Handaxe',4]],'Bardo':[['Dagger',2]],'Bruxo':[['Sickle',1],['Dagger',2]],'Clérigo':[['Mace',1]],'Druida':[['Sickle',1],['Quarterstaff',1]],'Feiticeiro':[['Spear',1],['Dagger',2]],'Guerreiro':[['Greatsword',1],['Flail',1],['Javelin',8]],'Ladino':[['Dagger',2],['Shortsword',1],['Shortbow',1]],'Mago':[['Dagger',2],['Quarterstaff',1]],'Monge':[['Spear',1],['Dagger',5]],'Paladino':[['Longsword',1],['Javelin',6]],'Patrulheiro':[['Scimitar',1],['Shortsword',1],['Longbow',1]]};
function syncStartingEquipment(){const x=c(),d=x.creationWizard;if(!d?.cls)return;const p=playState(),signature=[d.cls,d.background,d.classKit,d.bgKit].join('|');if(p.starterSignature===signature)return;p.weapons=p.weapons.filter(e=>!e.starter);p.inventory=p.inventory.filter(e=>!e.starter);let items=d.classKit==='gold'?[]:d.cls==='Guerreiro'&&d.classKit==='B'?[['Scimitar',1],['Shortsword',1],['Longbow',1]]:STARTER_WEAPONS[d.cls]||[];for(const [en,quantity] of items){const w=WEAPON_DATA.find(e=>e.en===en);if(!w)continue;p.inventory.push({id:crypto.randomUUID(),name:w.name,quantity,weight:Number(wentries('Equipamento').find(e=>e.name.toLowerCase()===en.toLowerCase())?.text.match(/(\d+(?:\.\d+)?)\s*(?:lb\.|1b\.)/)?.[1]||0),starter:true,equipped:true});p.weapons.push({id:crypto.randomUUID(),weapon:en,ability:'auto',magic:0,proficient:'auto',two:false,offhand:false,starter:true});}p.starterSignature=signature;}
