function openAbilityColor(i){const colors=DEFAULT_ABILITY_COLORS.concat(['#485963','#9b682d','#356e7c','#6b723b','#904032','#6b4c7a']);openPlayDialog('Cor · '+ATTR[i],`<p>Escolha uma cor para o atributo, sua salvaguarda e suas perícias.</p><div class="ability-swatches">${colors.map(color=>`<button aria-label="Cor ${color}" style="background:${color}" onclick="setAbilityColor(${i},'${color}')"></button>`).join('')}</div><label>Cor personalizada<input type="color" aria-label="Cor personalizada de ${ATTR[i]}" value="${abilityColor(i)}" oninput="setAbilityColor(${i},this.value)"></label>`);}
