sheetRoll=function(label,bonus=0,forcedDis=false,included=false){const target=label==='Iniciativa'?'initiative':label.startsWith('Salvaguarda de ')?'save:'+ATTR.indexOf(label.slice(15)):null;requestDice({rollKind:target==='initiative'?'initiative':target?'save':'attack',label,sides:20,count:1,bonus:bonus+(included||!target?0:additionalBonus(target)),forcedDis:forcedDis===true});};
roll=function(d,b){requestDice({label:'d'+d,sides:d,count:1,bonus:b});};
weaponRoll=function(id,damage=false){const e=playState().weapons.find(e=>e.id===id),n=weaponNumbers(c(),e);if(!n)return;if(!damage)return sheetRoll(n.w.name,n.bonus,n.heavy);const match=n.die.match(/(\d+)d(\d+)/);if(!match)return openPlayDialog('Dano · '+n.w.name,'<p>Dano fixo: '+Math.max(0,1+n.damage)+' '+n.w.type+'</p>');requestDice({rollKind:'damage',damageRoll:true,label:'Dano · '+n.w.name,count:+match[1],sides:+match[2],bonus:n.damage,min:0,note:n.w.type+' · confira crítico e efeitos adicionais.'});};
spendDie=function(name){const x=c(),cls=x.classes.find(p=>p.name===name);if(!cls||(x.hitDiceUsed[name]||0)>=cls.level)return toast('Nenhum Dado de Vida restante nessa classe.');let spent=false;const baseHP=x.hp;requestDice({label:'Dado de Vida · '+name,count:1,sides:HIT_DIE[name],bonus:mod(x.attrs[2]),min:0,apply:heal=>{if(!spent){x.hitDiceUsed[name]=(x.hitDiceUsed[name]||0)+1;spent=true;}x.hp=Math.min(x.maxhp,baseHP+heal);save();render();}});};
