// 2.7 — mídias locais por ataque, preservando GIFs animados.
function validAttackMedia(media){return media&&typeof media.data==='string'&&media.data.length<15000000&&/^data:image\/(gif|png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(media.data);}
function attackMediaView(key){const media=playState().attackMedia?.[key],valid=validAttackMedia(media);return `<div class="attack-media"><div class="attack-media-preview">${valid?`<img loading="lazy" src="${media.data}" alt="Arte do ataque · ${esc(media.name||'imagem enviada')}">`:''}</div><div class="attack-media-tools"><button aria-label="${valid?'Trocar imagem ou GIF':'Adicionar imagem ou GIF'}" title="Imagem / GIF" onclick="document.getElementById('attack-media-${key}').click()">${valid?'✎':'＋'}</button><input id="attack-media-${key}" hidden type="file" accept="image/gif,image/png,image/jpeg,image/webp" onchange="uploadAttackMedia(event,'${key}')">${valid?`<button aria-label="Remover imagem do ataque" onclick="removeAttackMedia('${key}')">×</button>`:''}</div></div>`;}
async function uploadAttackMedia(event,key){const file=event.target.files?.[0];event.target.value='';if(!file||!c()||!/^(weapon|manual):[a-zA-Z0-9_-]{1,80}$/.test(key))return;const charId=c().id;try{if(!['image/gif','image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1500000)throw Error('Escolha JPG, PNG, WebP ou GIF de até 1,5 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Não foi possível ler a imagem.'));reader.readAsDataURL(file);});const media={name:file.name.slice(0,80),data};if(!validAttackMedia(media))throw Error('Formato de imagem inválido.');await new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=()=>reject(Error('Não foi possível abrir esta imagem.'));img.src=data;});const char=db.chars.find(x=>x.id===charId);if(!char)return;const p=playInit(char);p.attackMedia=p.attackMedia||{};const previous=p.attackMedia[key];p.attackMedia[key]=media;try{localStorage.setItem('codice2024',JSON.stringify(db));}catch{if(previous)p.attackMedia[key]=previous;else delete p.attackMedia[key];throw Error('Não há espaço para salvar esta imagem. Use um arquivo menor ou remova outra mídia.');}save();render();toast('Mídia salva no ataque. O backup JSON também inclui a imagem.');}catch(error){toast(error.message||'Não foi possível adicionar a imagem.');}}
