const beforeWindPortrait=renderPortrait;renderPortrait=function(){beforeWindPortrait();const hero=document.querySelector('.hero');if(hero&&!hero.querySelector('.class-wind')){const wind=document.createElement('span');wind.className='class-wind';wind.setAttribute('aria-hidden','true');hero.appendChild(wind);}};
