function seedEpicWind(hero){if(!hero||!window.requestAnimationFrame)return;const layer=hero.querySelector('.class-wind');if(!layer||layer.querySelector('.wind-ribbon'))return;for(let i=0;i<5;i++){const ribbon=document.createElement('span');ribbon.className='wind-ribbon';const renew=()=>{const y=15+Math.random()*55,bend=-30+Math.random()*60;ribbon.innerHTML=`<svg viewBox="0 0 600 100" preserveAspectRatio="none"><path d="M0 ${y} Q150 ${y+bend} 300 ${y} T600 ${y-bend/2}"/><path d="M45 ${y+8} Q195 ${y+8-bend} 345 ${y+8} T645 ${y+8+bend/2}"/></svg>`;ribbon.style.top=(-10+Math.random()*100)+'%';ribbon.style.setProperty('--ribbon-time',(7+Math.random()*10)+'s');ribbon.style.setProperty('--ribbon-delay',(Math.random()*7)+'s');ribbon.style.setProperty('--ribbon-tilt',(-15+Math.random()*30)+'deg');ribbon.style.animation='none';void ribbon.offsetWidth;ribbon.style.animation='';};ribbon.addEventListener('animationend',renew);layer.appendChild(ribbon);renew();}}
function skillRules(){const p=playState();return p.skillRules||(p.skillRules={jack:false,reliable:false,notes:''});}
function skillBonus(i){const x=c(),training=Number(x.skills[i]||0);return mod(x.attrs[SKILLS[i][1]])+(training?training*pb():skillRules().jack?Math.floor(pb()/2):0)+(skillRules().magician&&[1,12].includes(i)?Math.max(1,mod(x.attrs[4])):0)+additionalBonus('skill:'+i);}
