function rollSkill(i){const trained=Number(c().skills[i]||0)>0,reliable=skillRules().reliable&&trained;requestDice({rollKind:'skill',label:SKILLS[i][0],sides:20,count:1,bonus:skillBonus(i),floorDie:reliable?10:0,note:reliable?'Reliable Talent: resultados de 1 a 9 no d20 contam como 10 para esta perícia.':undefined});}
