function initiativeBonus(){return mod(c().attrs[1])+Number(c().calc.initBonus||0)+additionalBonus('initiative');}
function saveBonus(i){return mod(c().attrs[i])+(c().saves.includes(i)?pb():0)+additionalBonus('save:'+i);}
function bonusTargets(){return [['allskills','Todas as perícias'],...SKILLS.map(([n],i)=>['skill:'+i,n]),['initiative','Iniciativa'],['allsaves','Todas as salvaguardas'],...ATTR.map((n,i)=>['save:'+i,'Salvaguarda · '+n])];}
function bonusValue(item){if(item.source==='pb')return pb();if(/^attr:[0-5]$/.test(item.source))return mod(c().attrs[Number(item.source.slice(5))]);return Number(item.amount)||0;}
function additionalBonus(target){return (skillRules().bonuses||[]).reduce((sum,item)=>{const matches=item.targets?.includes(target)||(target.startsWith('skill:')&&item.targets?.includes('allskills'))||(target.startsWith('save:')&&item.targets?.includes('allsaves'));return sum+(matches?bonusValue(item):0);},0);}
function bonusSummary(){return `<div class="bonus-list">${(skillRules().bonuses||[]).map((b,i)=>`<div class="bonus-row"><span>${esc(b.targets.map(t=>bonusTargets().find(([k])=>k===t)?.[1]||t).join(', '))}<small>${signed(bonusValue(b))} · ${esc(b.source==='pb'?'Proficiência':b.source.startsWith('attr:')?ATTR[Number(b.source.slice(5))]:'Valor fixo')}</small></span><button aria-label="Editar bônus ${i+1}" onclick="startAdditionalBonus(${i})">✎</button><button aria-label="Remover bônus ${i+1}" onclick="removeAdditionalBonus(${i})">×</button></div>`).join('')}</div>`;}
let additionalBonusDraft=null;
function startAdditionalBonus(index=-1){const old=skillRules().bonuses?.[index];additionalBonusDraft=old?{...old,targets:[...old.targets],index}:{targets:[],source:'pb',amount:0,index:-1};renderBonusStep(1);}
function renderBonusStep(step){const d=additionalBonusDraft;if(!d)return;const targets=bonusTargets(),options=[['pb','Modificador de Proficiência'],...ATTR.map((n,i)=>['attr:'+i,'Modificador de '+n]),['fixed','Número personalizado']];if(step===1)openPlayDialog('Bônus Adicional · 1 de 2',`<p>A quais perícias ou rolagens o bônus se aplica?</p><label>Adicionar destino<select id="bonus-target" onchange="addBonusTarget(this.value)"><option value="">Escolher…</option>${targets.filter(([k])=>!d.targets.includes(k)).map(([k,n])=>`<option value="${k}">${esc(n)}</option>`).join('')}</select></label><div class="bonus-targets">${d.targets.map(t=>`<button onclick="removeBonusTarget('${t}')">${esc(targets.find(([k])=>k===t)?.[1]||t)} ×</button>`).join('')||'<p class="muted">Escolha um ou mais destinos.</p>'}</div><button class="primary" ${d.targets.length?'':'disabled'} onclick="renderBonusStep(2)">Próximo</button>`);else openPlayDialog('Bônus Adicional · 2 de 2',`<p>Qual é a origem do bônus?</p><label>Bônus<select id="bonus-source" onchange="additionalBonusDraft.source=this.value;renderBonusStep(2)">${options.map(([k,n])=>`<option value="${k}" ${d.source===k?'selected':''}>${esc(n)}</option>`).join('')}</select></label>${d.source==='fixed'?`<label>Valor adicional<input id="bonus-amount" type="number" step="1" value="${Number(d.amount)||0}" oninput="additionalBonusDraft.amount=Number(this.value)"></label>`:'<p class="muted">O valor acompanha automaticamente a proficiência ou o atributo do personagem.</p>'}<div class="actions"><button onclick="renderBonusStep(1)">Voltar</button><button class="primary" onclick="commitAdditionalBonus()">Salvar bônus</button></div>`);}
function addBonusTarget(target){if(!additionalBonusDraft||!bonusTargets().some(([k])=>k===target))return;if(!additionalBonusDraft.targets.includes(target))additionalBonusDraft.targets.push(target);renderBonusStep(1);}
function removeBonusTarget(target){additionalBonusDraft.targets=additionalBonusDraft.targets.filter(t=>t!==target);renderBonusStep(1);}
function commitAdditionalBonus(){const d=additionalBonusDraft;if(!d||!d.targets.length)return;const r=skillRules();r.bonuses=r.bonuses||[];const item={targets:[...d.targets],source:d.source,amount:Number(d.amount)||0};if(d.index>=0)r.bonuses[d.index]=item;else r.bonuses.push(item);additionalBonusDraft=null;save();render();openSkillDetails();}
function removeAdditionalBonus(i){skillRules().bonuses.splice(i,1);save();render();openSkillDetails();}
let toastTimer=null,toastMotion=null,toastSerial=0;
function toast(message){const el=document.querySelector('#toast'),serial=++toastSerial;if(!el)return;if(typeof clearTimeout==='function')clearTimeout(toastTimer);toastMotion?.cancel?.();el.textContent=message;el.style.display='block';const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;if(el.animate&&!reduced)toastMotion=el.animate([{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'ease-out'});toastTimer=setTimeout(()=>{if(serial!==toastSerial)return;if(el.animate&&!reduced){toastMotion=el.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(16px)'}],{duration:220,easing:'ease-in'});toastMotion.finished.then(()=>{if(serial===toastSerial)el.style.display='none';},()=>{});}else el.style.display='none';},2800);}
