const COIN_TYPES=[['pp','Platina','#c9d8e5','P'],['gp','Ouro','#e7b952','O'],['ep','Electrum','#c9b783','E'],['sp','Prata','#c6cbd5','P'],['cp','Cobre','#be7b52','C']];
function coinValue(key){return key==='gp'?Number(c().money)||0:Number(c().coins?.[key])||0;}
function coinImage(key,color,letter){const name=COIN_TYPES.find(c=>c[0]===key)?.[1]||'',id='coin-metal-'+key,styles={pp:{light:'#f7f9ee',base:'#bbc9c1',dark:'#637e80',shape:'M24 6H76L91 23V77L76 94H24L9 77V23Z',rim:'M28 12H72L84 26V74L72 88H28L16 74V26Z',engraving:'M34 24 23 43H45Z M61 31 49 51H73Z M36 52 24 73H48Z M32 30 28 39H39Z M60 38 55 47H66Z M36 59 30 69H42Z M54 61 65 70 55 81 M64 58 77 70 66 83 M73 55 84 69 76 81'},gp:{light:'#fff2b3',base:'#d8aa4e',dark:'#90612d',shape:'M11 9H89Q71 50 89 91H11Q29 50 11 9Z',rim:'M21 17H79Q65 50 79 83H21Q35 50 21 17Z',engraving:'M39 66Q29 48 42 36Q49 28 61 35L69 29 74 35 64 41Q59 44 55 38Q41 37 39 48Q37 57 49 60L56 72 48 67 42 75 M45 43 50 49 60 52 51 55 M32 29 39 35 M60 27 64 21 M32 69 28 76'},ep:{light:'#f6f3cd',base:'#aeb9a9',dark:'#657e7c',shape:'M24 8H76C102 28 102 65 76 86H24C-2 65-2 28 24 8Z',rim:'M27 15H73C94 33 94 61 73 79H27C6 61 6 33 27 15Z',hole:[52,65,7],engraving:'M30 26 64 55 M65 24 30 56 M27 24Q18 31 25 38Q32 42 37 32 M66 25Q77 27 73 37 M30 52Q19 53 21 63 M62 46 70 39'},sp:{light:'#fcfff3',base:'#b9c6bd',dark:'#6a8483',shape:'M50 5 95 88H5Z',rim:'M50 18 83 81H17Z',hole:[50,57,7],engraving:'M50 25V36 M45 30H55 M31 69 27 76 M69 69 73 76 M34 71 38 69 M62 69 66 71 M50 35 53 39 50 42 47 39Z'},cp:{light:'#f2ba8d',base:'#b77b5a',dark:'#764c3e',shape:'M29 6H71L94 29V71L71 94H29L6 71V29Z',rim:'M33 14H67L86 33V67L67 86H33L14 67V33Z',hole:[50,50,8],engraving:'M33 25V38 M26 31H40 M67 25V38 M60 31H74 M33 64V77 M26 70H40 M67 64V77 M60 70H74 M22 46H30 M70 46H78 M24 55H31 M69 55H76'}};const c=styles[key];if(!c)return '';const hole=c.hole?` M${c.hole[0]+c.hole[2]} ${c.hole[1]}a${c.hole[2]} ${c.hole[2]} 0 1 0 -${c.hole[2]*2} 0a${c.hole[2]} ${c.hole[2]} 0 1 0 ${c.hole[2]*2} 0Z`:'';return `<svg viewBox="0 0 100 100" class="coin-image coin-${key}" role="img" aria-label="Moeda de ${name}"><defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${c.light}"/><stop offset=".28" stop-color="${c.base}"/><stop offset=".55" stop-color="${c.light}"/><stop offset=".78" stop-color="${c.base}"/><stop offset="1" stop-color="${c.dark}"/></linearGradient><filter id="${id}-grain" x="-10%" y="-10%" width="120%" height="120%"><feTurbulence type="fractalNoise" baseFrequency=".6" numOctaves="2" seed="${key.charCodeAt(0)}" result="noise"/><feComposite in="noise" in2="SourceAlpha" operator="in" result="cut"/><feBlend in="SourceGraphic" in2="cut" mode="soft-light"/></filter></defs><path d="${c.shape}${hole}" fill-rule="evenodd" fill="url(#${id})" stroke="${c.dark}" stroke-width="2"/><path d="${c.rim}" fill="none" stroke="${c.dark}" stroke-width="1.2" opacity=".7"/><path d="${c.engraving}" fill="none" stroke="${c.dark}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/><path d="${c.engraving}" transform="translate(-.7 -.7)" fill="none" stroke="${c.light}" stroke-width=".65" opacity=".8"/>${c.hole?`<circle cx="${c.hole[0]}" cy="${c.hole[1]}" r="${c.hole[2]+1.3}" fill="none" stroke="${c.dark}" stroke-width="1.1"/>`:''}<path d="${c.shape}${hole}" fill-rule="evenodd" fill="#ffffff" opacity=".07" filter="url(#${id}-grain)"/></svg>`;}

function currencyBar(){return `<div class="currency-wallet">${COIN_TYPES.map(([key,name,color,letter])=>`<label class="currency-item">${coinImage(key,color,letter)}<span>${name}</span><input type="number" min="0" step="1" aria-label="Peças de ${name}" value="${coinValue(key)}" onchange="setCoin('${key}',this.value)"></label>`).join('')}</div>`;}
function setCoin(key,value){if(!COIN_TYPES.some(([k])=>k===key))return;const n=Math.max(0,Math.min(999999999,Math.floor(Number(value)||0)));if(key==='gp')c().money=n;else{c().coins=c().coins||{};c().coins[key]=n;}save();}
