function seedEmittedSparks(){if(!window.requestAnimationFrame||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;const emitters=[...document.querySelectorAll('.inspiration-active .star-art'),...document.querySelectorAll('.skill-training.state-2 .training-box')];for(const source of emitters){if(source.dataset.emitting==='true')continue;source.dataset.emitting='true';const emit=()=>{if(!source.isConnected)return;const spark=document.createElement('i'),star=source.classList.contains('star-art'),angle=Math.random()*Math.PI*2,dist=(star?32:14)+Math.random()*(star?40:22);spark.className='emitted-spark';const dx=Math.cos(angle)*dist,dy=Math.sin(angle)*dist;spark.style.setProperty('--spark-x',dx+'px');spark.style.setProperty('--spark-y',dy+'px');spark.style.setProperty('--spark-mid-x',(dx*.45+(Math.random()-.5)*12)+'px');spark.style.setProperty('--spark-mid-y',(dy*.45+(Math.random()-.5)*12)+'px');spark.style.setProperty('--spark-life',(star?2400+Math.random()*2600:1000+Math.random()*1400)+'ms');spark.style.width=spark.style.height=(1+Math.random()*2)+'px';source.appendChild(spark);spark.addEventListener('animationend',()=>spark.remove(),{once:true});setTimeout(emit,star?500+Math.random()*1100:300+Math.random()*800);};setTimeout(emit,Math.random()*600);}}
