seedEpicWind=function(hero){const layer=hero?.querySelector('.class-wind');if(!layer||layer.dataset.continuous)return;layer.dataset.continuous='true';layer.innerHTML=Array.from({length:6},(_,i)=>`<span class="wind-loop" style="--wind-y:${12+i*14}%;--wind-time:${10+i*2.3}s;--wind-delay:-${i*3.7}s"><svg viewBox="0 0 1200 120" preserveAspectRatio="none"><path d="M-100 55Q50 5 200 55T500 55T800 55T1100 55T1400 55"/><path d="M-100 66Q50 16 200 66T500 66T800 66T1100 66T1400 66"/></svg></span>`).join('');};
