let attackMediaDatabase=null;
function mediaDatabase(){if(attackMediaDatabase)return attackMediaDatabase;attackMediaDatabase=new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('Armazenamento de imagens indisponível.'));const req=indexedDB.open('codice-attack-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('media');req.onerror=()=>reject(req.error);req.onsuccess=()=>resolve(req.result);});return attackMediaDatabase;}
async function writeAttackMedia(key,media){const database=await mediaDatabase();return new Promise((resolve,reject)=>{const tx=database.transaction('media','readwrite');tx.objectStore('media').put(media,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
uploadAttackMedia=async function(event,key){const file=event.target.files?.[0];event.target.value='';if(!file||!c()||!/^(weapon|manual):[a-zA-Z0-9_-]{1,80}$/.test(key))return;const charId=c().id;try{if(!['image/gif','image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Escolha JPG, PNG, WebP ou GIF de até 10 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Não foi possível ler a imagem.'));reader.readAsDataURL(file);});await new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=()=>reject(Error('Imagem inválida.'));img.src=data;});const char=db.chars.find(x=>x.id===charId);if(!char)return;const media={name:file.name.slice(0,80),data,storageKey:charId+':'+key};await writeAttackMedia(media.storageKey,media);const p=playInit(char);p.attackMedia=p.attackMedia||{};p.attackMedia[key]=media;save();render();toast('Imagem / GIF salvo.');}catch(error){toast(error.message||'Não foi possível salvar a imagem.');}};
async function restoreAttackMedia(){if(!window.indexedDB)return;try{const database=await mediaDatabase();const tasks=[];for(const char of db.chars)for(const media of Object.values(char.play?.attackMedia||{})){if(!media.storageKey||media.data)continue;tasks.push(new Promise(resolve=>{const req=database.transaction('media','readonly').objectStore('media').get(media.storageKey);req.onsuccess=()=>{if(req.result?.data)media.data=req.result.data;resolve();};req.onerror=()=>resolve();}));}await Promise.all(tasks);if(tasks.length)render();}catch{toast('Não foi possível carregar as imagens salvas.');}}
restoreAttackMedia();
